-- classes carry their archetype. max_armour_weight is the CEILING a class may wear, which is
-- a DIFFERENT fact from an item's own armour_weight and must never be populated from it
-- (DECISIONS.md, 2026-09-12). It is Pierre-sourced, not armory-derivable, and unknown for all
-- twelve — so it is nullable and stays NULL. An empty field is a feature; a guess is a bug.
CREATE TABLE classes (
    id                serial PRIMARY KEY,
    archetype_id      integer     NOT NULL REFERENCES archetypes(id),
    slug              varchar(64) NOT NULL UNIQUE,
    name              varchar(64) NOT NULL UNIQUE,
    max_armour_weight integer     NULL REFERENCES armour_weights(id)
);

